document.addEventListener('DOMContentLoaded', function () {
	function initHubspotResourceForms() {
		if (!window.hbspt || !window.hbspt.forms) return;

		document.querySelectorAll('.hubspot-form-target').forEach(function (el) {
			if (el.dataset.loaded === 'true') return;

			window.hbspt.forms.create({
				portalId: el.dataset.portalId,
				formId: el.dataset.formId,
				target: '#' + el.id
			});

			el.dataset.loaded = 'true';
		});
	}

	if (window.hbspt && window.hbspt.forms) {
		initHubspotResourceForms();
	} else {
		var hubspotInterval = setInterval(function () {
			if (window.hbspt && window.hbspt.forms) {
				clearInterval(hubspotInterval);
				initHubspotResourceForms();
			}
		}, 300);
	}
});

