jQuery(function($){

	// Prevent modal "outside click" logic from hijacking datepicker interaction
	$(document).on('mousedown click', '#ui-datepicker-div, #ui-datepicker-div *', function(e){
		e.stopPropagation();
	});

	function enhanceGFDatepickerInModal($modal){
		if (!$modal || !$modal.length) return;

		// Ensure GF has initialized its datepicker first
		if (typeof window.gformInitDatepicker === 'function') {
			try { window.gformInitDatepicker(); } catch(e) {}
		}

		const $inputs = $modal.find('input.gform-datepicker, input.datepicker');
		if (!$inputs.length) return;

		$inputs.each(function(){
			const $input = $(this);

			// If datepicker isn't attached yet, bail (we'll try again next tick)
			if (typeof $input.datepicker !== 'function') return;

			// IMPORTANT: do NOT destroy/recreate — just override options
			try {
				$input.datepicker('option', 'beforeShow', function(){
					setTimeout(function(){
						// Keep the calendar inside the modal so clicks aren't treated as "outside"
						$('#ui-datepicker-div').appendTo($modal).css({ zIndex: 999999 });
					}, 0);
				});

				$input.datepicker('option', 'onSelect', function(dateText){
					// Debug: see if this fires
					// console.log('GF date selected:', dateText);

					$input.val(dateText);

					// Force Gravity Forms / any validation scripts to register it
					$input.trigger('input').trigger('change').trigger('blur');

					// Some modal scripts re-focus/clear — re-apply shortly after
					setTimeout(function(){
						if ($input.val() !== dateText) {
							$input.val(dateText).trigger('change');
						}
					}, 10);
				});
			} catch(e) {}
		});
	}

	// Open/close modal (your existing behavior)
	$(document).on('click', '.modal-toggle', function(e){
		e.preventDefault();
		const targetModalId = $(this).data('target');
		const $modal = targetModalId ? $(targetModalId) : $(this).closest('.modal');
		$modal.toggleClass('is-visible');

		if ($modal.hasClass('is-visible')) {
			// wait for modal to be visible before wiring datepicker behavior
			setTimeout(function(){
				enhanceGFDatepickerInModal($modal);
			}, 50);
		}
	});

	// If GF rerenders via AJAX, re-apply within open modal
	$(document).on('gform_post_render gform_page_loaded', function(){
		const $openModal = $('.modal.is-visible').first();
		if ($openModal.length) {
			setTimeout(function(){
				enhanceGFDatepickerInModal($openModal);
			}, 50);
		}
	});

});
